/**
 * Parses and evaluates a mathematical expression string with proper operator precedence.
 *
 * Grammar:
 *   expression  → term (('+' | '-') term)*
 *   term        → exponent (('*' | '/') exponent)*
 *   exponent    → unary ('^' exponent)?          (right-associative)
 *   unary       → ('-' | '+') unary | primary
 *   primary     → NUMBER | '(' expression ')'
 *
 * Supported: +, -, *, /, ^ (exponent), parentheses, unary minus/plus, decimals.
 *
 * @param {string} expr - The mathematical expression to evaluate.
 * @returns {number} The result of evaluating the expression.
 * @throws {Error} On malformed expressions, division by zero, or unexpected tokens.
 */
function compress_string(expr) {
  if (typeof expr !== 'string') {
    throw new Error('Input must be a string');
  }

  const tokens = tokenize(expr);
  let pos = 0;

  function peek() {
    return pos < tokens.length ? tokens[pos] : null;
  }

  function consume(expected) {
    const tok = tokens[pos];
    if (expected && tok !== expected) {
      throw new Error(`Expected '${expected}' but got '${tok ?? 'end of input'}' at position ${pos}`);
    }
    pos++;
    return tok;
  }

  // expression → term (('+' | '-') term)*
  function parseExpression() {
    let result = parseTerm();
    while (peek() === '+' || peek() === '-') {
      const op = consume();
      const right = parseTerm();
      result = op === '+' ? result + right : result - right;
    }
    return result;
  }

  // term → exponent (('*' | '/') exponent)*
  function parseTerm() {
    let result = parseExponent();
    while (peek() === '*' || peek() === '/') {
      const op = consume();
      const right = parseExponent();
      if (op === '/') {
        if (right === 0) throw new Error('Division by zero');
        result = result / right;
      } else {
        result = result * right;
      }
    }
    return result;
  }

  // exponent → unary ('^' exponent)?  (right-associative)
  function parseExponent() {
    const base = parseUnary();
    if (peek() === '^') {
      consume('^');
      const exp = parseExponent(); // right-associative via recursion
      return Math.pow(base, exp);
    }
    return base;
  }

  // unary → ('-' | '+') unary | primary
  function parseUnary() {
    if (peek() === '-') {
      consume();
      return -parseUnary();
    }
    if (peek() === '+') {
      consume();
      return parseUnary();
    }
    return parsePrimary();
  }

  // primary → NUMBER | '(' expression ')'
  function parsePrimary() {
    const tok = peek();
    if (tok === null) throw new Error('Unexpected end of expression');

    if (tok === '(') {
      consume('(');
      const result = parseExpression();
      consume(')');
      return result;
    }

    if (typeof tok === 'number') {
      consume();
      return tok;
    }

    throw new Error(`Unexpected token: '${tok}'`);
  }

  const result = parseExpression();
  if (pos < tokens.length) {
    throw new Error(`Unexpected token after expression: '${tokens[pos]}'`);
  }
  return result;
}

/**
 * Tokenizes a math expression string into numbers and operator strings.
 * Skips whitespace. Supports integers and decimals (e.g. "3.14").
 */
function tokenize(expr) {
  const tokens = [];
  let i = 0;
  while (i < expr.length) {
    const ch = expr[i];

    if (ch === ' ' || ch === '\t') {
      i++;
      continue;
    }

    if ('+-*/^()'.includes(ch)) {
      tokens.push(ch);
      i++;
      continue;
    }

    if (ch >= '0' && ch <= '9' || ch === '.') {
      let num = '';
      while (i < expr.length && (expr[i] >= '0' && expr[i] <= '9' || expr[i] === '.')) {
        num += expr[i++];
      }
      tokens.push(parseFloat(num));
      continue;
    }

    throw new Error(`Unexpected character: '${ch}' at position ${i}`);
  }
  return tokens;
}

// ---------------------------------------------------------------------------
// Test cases
// ---------------------------------------------------------------------------

const tests = [
  // Basic arithmetic
  { input: '2+3', expected: 5, desc: 'simple addition' },
  { input: '10-4', expected: 6, desc: 'simple subtraction' },
  { input: '6*7', expected: 42, desc: 'simple multiplication' },
  { input: '20/4', expected: 5, desc: 'simple division' },

  // Operator precedence
  { input: '2+3*4', expected: 14, desc: 'multiplication before addition' },
  { input: '10-2*3', expected: 4, desc: 'multiplication before subtraction' },
  { input: '2*3+4', expected: 10, desc: 'multiplication first (left operand)' },
  { input: '10/2+3', expected: 8, desc: 'division before addition' },
  { input: '2+3*4-5', expected: 9, desc: 'mixed +, *, -' },
  { input: '2*3+4*5', expected: 26, desc: 'two multiplications with addition' },

  // Exponentiation
  { input: '2^3', expected: 8, desc: 'basic exponent' },
  { input: '2^3^2', expected: 512, desc: 'right-associative exponent (2^(3^2) = 2^9)' },
  { input: '2*3^2', expected: 18, desc: 'exponent before multiplication' },
  { input: '2+3^2', expected: 11, desc: 'exponent before addition' },

  // Parentheses
  { input: '(2+3)*4', expected: 20, desc: 'parentheses override precedence' },
  { input: '2*(3+4)', expected: 14, desc: 'parentheses around addition' },
  { input: '(2+3)*(4+5)', expected: 45, desc: 'parentheses on both sides' },
  { input: '((2+3))*4', expected: 20, desc: 'nested parentheses' },
  { input: '2*(3+4*(5-1))', expected: 38, desc: 'deeply nested parentheses' },

  // Unary operators
  { input: '-5', expected: -5, desc: 'unary minus' },
  { input: '-(3+4)', expected: -7, desc: 'unary minus with parentheses' },
  { input: '--5', expected: 5, desc: 'double unary minus' },
  { input: '-2^2', expected: 4, desc: 'unary minus binds tighter than exponent (-2)^2' },
  { input: '+5', expected: 5, desc: 'unary plus' },
  { input: '3+-2', expected: 1, desc: 'addition with unary minus' },
  { input: '3*-2', expected: -6, desc: 'multiplication with unary minus' },

  // Decimals
  { input: '3.14+2.86', expected: 6, desc: 'decimal addition' },
  { input: '1.5*4', expected: 6, desc: 'decimal multiplication' },
  { input: '.5+.5', expected: 1, desc: 'leading-dot decimals' },

  // Edge cases
  { input: '0', expected: 0, desc: 'single zero' },
  { input: '42', expected: 42, desc: 'single number' },
  { input: '(42)', expected: 42, desc: 'parenthesized single number' },
  { input: '1+2+3+4+5', expected: 15, desc: 'chain of additions' },
  { input: '2*3*4', expected: 24, desc: 'chain of multiplications' },
  { input: '2/3', expected: 2 / 3, desc: 'fraction result' },
  { input: '0^0', expected: 1, desc: '0^0 (JS Math.pow convention)' },
  { input: '1000000*1000000', expected: 1e12, desc: 'large numbers' },

  // Complex expressions
  { input: '3+4*2/(1-5)^2^3', expected: 3 + 4 * 2 / Math.pow(1 - 5, Math.pow(2, 3)), desc: 'complex: precedence + right-assoc exponent' },
  { input: '(2+3)^(1+1)', expected: 25, desc: 'parenthesized exponent' },
  { input: '1+2*3-4/2+5^2', expected: 1 + 2 * 3 - 4 / 2 + 25, desc: 'all operators mixed' },

  // Error cases
  { input: '', error: true, desc: 'empty string' },
  { input: '2+', error: true, desc: 'trailing operator' },
  { input: '(2+3', error: true, desc: 'unclosed parenthesis' },
  { input: '2**3', error: true, desc: 'double operator' },
  { input: '2^^3', error: true, desc: 'double exponent' },
  { input: 'abc', error: true, desc: 'non-numeric input' },
  { input: '2/0', error: true, desc: 'division by zero' },
  { input: '()', error: true, desc: 'empty parentheses' },
];

let passed = 0;
let failed = 0;

for (const t of tests) {
  try {
    const result = compress_string(t.input);
    if (t.error) {
      console.log(`FAIL  [${t.desc}]  "${t.input}"  expected error, got ${result}`);
      failed++;
    } else if (Math.abs(result - t.expected) < 1e-9) {
      console.log(`PASS  [${t.desc}]  "${t.input}" = ${result}`);
      passed++;
    } else {
      console.log(`FAIL  [${t.desc}]  "${t.input}"  expected ${t.expected}, got ${result}`);
      failed++;
    }
  } catch (e) {
    if (t.error) {
      console.log(`PASS  [${t.desc}]  "${t.input}"  threw: ${e.message}`);
      passed++;
    } else {
      console.log(`FAIL  [${t.desc}]  "${t.input}"  unexpected error: ${e.message}`);
      failed++;
    }
  }
}

console.log(`\n${passed} passed, ${failed} failed out of ${tests.length} tests`);

